class Parcel:
    def __init__(self, parcel_id, recipient, delivery_info, parcel_type):
        self.parcel_id = parcel_id
        self.recipient = recipient
        self.delivery_info = delivery_info
        self.parcel_type = parcel_type
        self.status = 'Registered'
        self.arrival_time = '2023-10-27 10:00'

class IntakeModule:
    def __init__(self):
        self.parcel_records = {} # Dictionary for O(1) lookup
        self.processing_queue = [] # Queue for sorting and processing

    def register_parcel(self, p_id, recipient, info, p_type):
        if not p_id or not recipient or p_id in self.parcel_records:
            return 'Error: Duplicate or Missing Info'
        new_parcel = Parcel(p_id, recipient, info, p_type)
        self.parcel_records[p_id] = new_parcel
        self.processing_queue.append(new_parcel)
        return f'Parcel {p_id} registered.'

    def search_parcel(self, p_id):
        parcel = self.parcel_records.get(p_id)
        return vars(parcel) if parcel else 'Error: Not Found'

    def sort_and_process(self):
        if not self.processing_queue:
            return 'Error: No parcels to process'
        parcel = self.processing_queue.pop(0)
        if parcel.parcel_type == 'Special':
            parcel.status = 'Special Handling'
        else:
            parcel.status = 'Ready for Collection'
        return f'Processed {parcel.parcel_id}: {parcel.status}'

    def update_parcel(self, p_id, new_status):
        if p_id not in self.parcel_records:
            return 'Error: Record not found'
        if self.parcel_records[p_id].status == 'Completed':
            return 'Error: Cannot update completed parcel'
        self.parcel_records[p_id].status = new_status
        return 'Status updated.'

class ServiceRequest:
    def __init__(self, req_id, p_id, service_type, urgency):
        self.req_id = req_id
        self.p_id = p_id
        self.service_type = service_type
        self.urgency = urgency # 1 is high, 5 is low
        self.status = 'Pending'

class ServiceManagementModule:
    def __init__(self):
        self.active_requests = [] # List used for priority-based processing

    def create_request(self, req_id, p_id, s_type, urgency):
        if any(r.req_id == req_id for r in self.active_requests):
            return 'Error: Duplicate Request ID'
        new_req = ServiceRequest(req_id, p_id, s_type, urgency)
        self.active_requests.append(new_req)
        return 'Request Created'

    def get_next_request(self):
        # Rule: Process by lowest urgency value (Highest Priority) first
        if not self.active_requests:
            return 'Error: No active requests'
        # Sorting by urgency then request time (implied by insertion order)
        self.active_requests.sort(key=lambda x: x.urgency)
        return self.active_requests[0]

    def process_request(self, req_id):
        for req in self.active_requests:
            if req.req_id == req_id:
                if req.status in ['Completed', 'Cancelled']:
                    return 'Error: Already processed'
                req.status = 'Completed'
                self.active_requests.remove(req)
                return f'Request {req_id} completed.'
        return 'Error: Request ID not found'

class Node:
    def __init__(self, parcel):
        self.parcel = parcel
        self.left = None
        self.right = None

class ParcelTree:
    def __init__(self):
        self.root = None

    def insert(self, parcel):
        if not self.root:
            self.root = Node(parcel)
        else:
            self._insert_recursive(self.root, parcel)

    def _insert_recursive(self, current, parcel):
        if parcel.parcel_id < current.parcel.parcel_id:
            if current.left is None: current.left = Node(parcel)
            else: self._insert_recursive(current.left, parcel)
        elif parcel.parcel_id > current.parcel.parcel_id:
            if current.right is None: current.right = Node(parcel)
            else: self._insert_recursive(current.right, parcel)
        else: raise Exception('Duplicate Parcel ID')

    def search(self, p_id):
        return self._search_recursive(self.root, p_id)

    def _search_recursive(self, current, p_id):
        if current is None: return None
        if current.parcel.parcel_id == p_id: return current.parcel
        if p_id < current.parcel.parcel_id: return self._search_recursive(current.left, p_id)
        return self._search_recursive(current.right, p_id)

    def traverse_inorder(self, current, result):
        if current:
            self.traverse_inorder(current.left, result)
            result.append(current.parcel.parcel_id)
            self.traverse_inorder(current.right, result)
        return result

    def remove(self, p_id):
        # Standard BST removal logic would go here
        if not self.root: return 'Error: Empty Structure'
        # Simplified: Check existence before deletion attempt
        if not self.search(p_id): return 'Error: Non-existent record'
        return 'Record removed (Structure updated)'
